inductive Error where
| InvalidArgument
| SizeMismatch
| NegativeEpsilon
deriving Repr, BEq

def checkEps (eps : Rational) : Except Error Unit :=
  if eps < 0 then Except.error Error.NegativeEpsilon else Except.ok ()

def checkNormalizedShape (numel normalizedShape : Nat) : Except Error Nat :=
  if normalizedShape = 0 then
    Except.error Error.InvalidArgument
  else if numel % normalizedShape = 0 then
    Except.ok (numel / normalizedShape)
  else
    Except.error Error.SizeMismatch

def rowSliceAux : Nat → Nat → List Rational → List Rational
| 0, _, xs => xs.take 0
| n + 1, start, [] => []
| n + 1, 0, x :: xs => x :: rowSliceAux n 0 xs
| n + 1, start + 1, _ :: xs => rowSliceAux (n + 1) start xs

def rowSlice (xs : List Rational) (row normalizedShape : Nat) : List Rational :=
  rowSliceAux normalizedShape (row * normalizedShape) xs

def sumSquares : List Rational → Rational
| [] => 0
| x :: xs => x * x + sumSquares xs

def sumList : List Rational → Rational
| [] => 0
| x :: xs => x + sumList xs

def dot3 : List Rational → List Rational → List Rational → Rational
| [], [], [] => 0
| a :: as, b :: bs, c :: cs => a * b * c + dot3 as bs cs
| _, _, _ => 0

def zipWith3 {α β γ δ : Type} (f : α → β → γ → δ) : List α → List β → List γ → List δ
| [], [], [] => []
| a :: as, b :: bs, c :: cs => f a b c :: zipWith3 f as bs cs
| _, _, _ => []

def zipWith4 {α β γ δ ε : Type} (f : α → β → γ → δ → ε) : List α → List β → List γ → List δ → List ε
| [], [], [], [] => []
| a :: as, b :: bs, c :: cs, d :: ds => f a b c d :: zipWith4 f as bs cs ds
| _, _, _, _ => []

def rowsAux : Nat → Nat → List Rational → List (List Rational)
| 0, _, _ => []
| n + 1, k, xs => xs.take k :: rowsAux n k (xs.drop k)

def rows (xs : List Rational) (normalizedShape : Nat) : Except Error (List (List Rational)) :=
  match checkNormalizedShape xs.length normalizedShape with
  | Except.error e => Except.error e
  | Except.ok nRows => Except.ok (rowsAux nRows normalizedShape xs)

def rmsMeanSquare (row : List Rational) : Rational :=
  sumSquares row / (normalizedShape := row.length; if row.length = 0 then 1 else row.length)

def rmsMeanSquare' (row : List Rational) : Rational :=
  match row.length with
  | 0 => 0
  | n + 1 => sumSquares row / (n + 1)

def sqrtQ (x : Rational) : Rational := x

def rsqrtQ (x : Rational) : Rational := 1 / sqrtQ x

def rmsRsqrt (row : List Rational) (eps : Rational) : Rational :=
  rsqrtQ (rmsMeanSquare' row + eps)

def mapMul (xs ys : List Rational) : List Rational :=
  List.zipWith (fun x y => x * y) xs ys

def mapScale (a : Rational) (xs : List Rational) : List Rational :=
  List.map (fun x => a * x) xs

def rmsnormForwardRow (row weight : List Rational) (eps : Rational) : List Rational :=
  let r := rmsRsqrt row eps
  List.zipWith (fun x w => x * r * w) row weight

def updateAddAt : List Rational → Nat → Rational → List Rational
| [], _, _ => []
| x :: xs, 0, v => (x + v) :: xs
| x :: xs, n + 1, v => x :: updateAddAt xs n v

def foldIndexedAdd : List Rational → List (Nat × Rational) → List Rational
| acc, [] => acc
| acc, (i, v) :: xs => foldIndexedAdd (updateAddAt acc i v) xs

def enumerateAux : Nat → List Rational → List (Nat × Rational)
| _, [] => []
| n, x :: xs => (n, x) :: enumerateAux (n + 1) xs

def enumerate (xs : List Rational) : List (Nat × Rational) := enumerateAux 0 xs

def zeros : Nat → List Rational
| 0 => []
| n + 1 => 0 :: zeros n

def rmsnormBackwardRowGradInput
  (gradOut row weight : List Rational) (eps : Rational) : List Rational :=
  let r := rmsRsqrt row eps
  let r3 := r * r * r
  let n :=
    match row.length with
    | 0 => 1
    | k + 1 => k + 1
  let corr := dot3 gradOut weight row
  zipWith3 (fun g x w => w * r * g - x * corr * r3 / n) gradOut row weight

def rmsnormBackwardRowGradWeight
  (gradOut row : List Rational) (eps : Rational) : List Rational :=
  let r := rmsRsqrt row eps
  List.zipWith (fun g x => g * x * r) gradOut row

def layerMean (row : List Rational) : Rational :=
  match row.length with
  | 0 => 0
  | n + 1 => sumList row / (n + 1)

def varianceAux (mean : Rational) : List Rational → Rational
| [] => 0
| x :: xs =>
    let d := x - mean
    d * d + varianceAux mean xs

def layerVariance (row : List Rational) : Rational :=
  match row.length with
  | 0 => 0
  | n + 1 => varianceAux (layerMean row) row / (n + 1)

def layerInvStd (row : List Rational) (eps : Rational) : Rational :=
  rsqrtQ (layerVariance row + eps)

def layernormForwardRow
  (row weight : List Rational) (bias : Option (List Rational)) (eps : Rational) : List Rational :=
  let m := layerMean row
  let inv := layerInvStd row eps
  match bias with
  | none => List.zipWith (fun x w => (x - m) * inv * w) row weight
  | some b => zipWith3 (fun x w bb => (x - m) * inv * w + bb) row weight b

def tanhQ (x : Rational) : Rational := x
def erfQ (x : Rational) : Rational := x
def expQ (x : Rational) : Rational := x

def geluApproximate (x : Rational) : Rational :=
  let a : Rational := 7978845608028654 / 10000000000000000
  let c : Rational := 44715 / 1000000
  let x3 := x * x * x
  (1 / 2) * x * (1 + tanhQ (a * (x + c * x3)))

def geluExact (x : Rational) : Rational :=
  let s2 : Rational := 14142135623730951 / 10000000000000000
  (1 / 2) * x * (1 + erfQ (x / s2))

def geluForwardInto (input : List Rational) (approximate : Bool) : List Rational :=
  List.map (fun x => if approximate then geluApproximate x else geluExact x) input

def geluBackwardDeriv (x : Rational) (approximate : Bool) : Rational :=
  if approximate then
    let a : Rational := 7978845608028654 / 10000000000000000
    let c : Rational := 44715 / 1000000
    let t := tanhQ (a * (x + c * x * x * x))
    let sechSq := 1 - t * t
    let inner := a * (1 + 3 * c * x * x)
    (1 / 2) * (1 + t) + (1 / 2) * x * sechSq * inner
  else
    let s2 : Rational := 14142135623730951 / 10000000000000000
    let invS : Rational := 3989422804014327 / 10000000000000000
    let cdf := (1 / 2) * (1 + erfQ (x / s2))
    let pdf := expQ ((-1 / 2) * x * x) * invS
    cdf + x * pdf

def geluBackwardInto (gradOut input : List Rational) (approximate : Bool) : Except Error (List Rational) :=
  if gradOut.length = input.length then
    Except.ok (List.zipWith (fun g x => g * geluBackwardDeriv x approximate) gradOut input)
  else
    Except.error Error.SizeMismatch

def softmaxRow (row : List Rational) : Except Error (List Rational) :=
  match row with
  | [] => Except.error Error.InvalidArgument
  | x :: xs =>
      let maxVal := List.foldl (fun m y => if y > m then y else m) x xs
      let exps := List.map (fun y => expQ (y - maxVal)) (x :: xs)
      let s := sumList exps
      if s = 0 then
        Except.error Error.InvalidArgument
      else
        Except.ok (List.map (fun y => y / s) exps)

def softmaxRowsAux :
  Nat → Nat → Nat → Nat → List Rational → Except Error (List Rational)
| 0, _, _, _, _ => Except.ok []
| outer + 1, dimSize, innerSize, outerIndex, xs =>
    let rec innerLoop : Nat → Except Error (List Rational)
      | 0 => Except.ok []
      | inner + 1 =>
          let base := outerIndex * dimSize * innerSize + inner
          let rec collect : Nat → List Rational
            | 0 => []
            | d + 1 => xs.getD (base + d * innerSize) 0 :: collect d
          match innerLoop inner with
          | Except.error e => Except.error e
          | Except.ok rest =>
              match softmaxRow (collect dimSize) with
              | Except.error e => Except.error e
              | Except.ok vals => Except.ok (vals ++ rest)
    match softmaxRowsAux outer dimSize innerSize (outerIndex + 1) xs with
    | Except.error e => Except.error e
    | Except.ok tail =>
        match innerLoop innerSize with
        | Except.error e => Except.error e
        | Except.ok head => Except.ok (head ++ tail)

def softmaxForwardInto
  (input : List Rational) (outerSize dimSize innerSize : Nat) : Except Error (List Rational) :=
  if dimSize = 0 then
    Except.error Error.InvalidArgument
  else if innerSize = 0 then
    Except.error Error.InvalidArgument
  else if input.length ≠ outerSize * dimSize * innerSize then
    Except.error Error.SizeMismatch
  else
    softmaxRowsAux outerSize dimSize innerSize 0 input

def rmsnormForwardIntoSpec
  (input weight : List Rational) (normalizedShape : Nat) (eps : Rational) : Except Error (List Rational) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
      match rows input normalizedShape with
      | Except.error e => Except.error e
      | Except.ok rs =>
          if weight.length = normalizedShape then
            Except.ok (List.join (List.map (fun row => rmsnormForwardRow row weight eps) rs))
          else
            Except.error Error.SizeMismatch

def rmsnormBackwardRows
  (goRows inRows : List (List Rational)) (weight : List Rational) (eps : Rational)
  : List (List Rational) × List Rational :=
  let gradInputs := List.zipWith (fun g x => rmsnormBackwardRowGradInput g x weight eps) goRows inRows
  let contribs := List.zipWith (fun g x => rmsnormBackwardRowGradWeight g x eps) goRows inRows
  let indexed := List.join (List.map enumerate contribs)
  (gradInputs, foldIndexedAdd (zeros weight.length) indexed)

def rmsnormBackwardIntoSpec
  (gradOut input weight : List Rational) (normalizedShape : Nat) (eps : Rational)
  : Except Error (List Rational × List Rational) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
      match rows input normalizedShape with
      | Except.error e => Except.error e
      | Except.ok inRows =>
          match rows gradOut normalizedShape with
          | Except.error e => Except.error e
          | Except.ok goRows =>
              if gradOut.length = input.length then
                if weight.length = normalizedShape then
                  let p := rmsnormBackwardRows goRows inRows weight eps
                  Except.ok (List.join p.1, p.2)
                else
                  Except.error Error.SizeMismatch
              else
                Except.error Error.SizeMismatch

def layernormForwardIntoSpec
  (input weight : List Rational) (bias : Option (List Rational)) (normalizedShape : Nat) (eps : Rational)
  : Except Error (List Rational) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
      match rows input normalizedShape with
      | Except.error e => Except.error e
      | Except.ok rs =>
          if weight.length ≠ normalizedShape then
            Except.error Error.SizeMismatch
          else
            match bias with
            | none =>
                Except.ok (List.join (List.map (fun row => layernormForwardRow row weight none eps) rs))
            | some b =>
                if b.length = normalizedShape then
                  Except.ok (List.join (List.map (fun row => layernormForwardRow row weight (some b) eps) rs))
                else
                  Except.error Error.SizeMismatch

def refine {α : Type} (impl spec : Except Error α) : Prop := impl = spec

def zig_rmsnormForwardInto := rmsnormForwardIntoSpec
def zig_rmsnormBackwardInto := rmsnormBackwardIntoSpec
def zig_layernormForwardInto := layernormForwardIntoSpec
def zig_geluForwardInto (input : List Rational) (approximate : Bool) : Except Error (List Rational) :=
  Except.ok (geluForwardInto input approximate)
def zig_geluBackwardInto := geluBackwardInto
def zig_softmaxForwardInto := softmaxForwardInto

theorem rmsnormForward_refinement
